import java.util.Arrays;
import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;

    private static final int ROOT = 3;

    private static long modPow(long a, long p) {
        if (p == 0) {
            return 1;
        }
        long half = modPow(a, p / 2);
        long ans = (half * half) % MOD;
        if (p % 2 == 1) {
            ans = (ans * a) % MOD;
        }
        return ans;
    }

    private static long modInv(long a) {
        return modPow(a, MOD - 2);
    }

    private static int bitReverse(int n, int k) {
        int result = 0;
        for (int i = 0; i < k; i++) {
            result = (result << 1) | (n & 1);
            n >>= 1;
        }
        return result;
    }

    private static long[] numberTheoreticTransform(long[] a, int k, boolean inverse) {
        int n = 1 << k;
        long[] result = new long[n];
        for (int i = 0; i < n; i++) {
            result[bitReverse(i, k)] = a[i];
        }

        for (int s = 0; s < k; s++) {
            int m = 1 << s;
            int m2 = m * 2;
            long wm = modPow(ROOT, (MOD - 1) / m2);
            if (inverse) {
                wm = modInv(wm);
            }
            for (int i = 0; i < n; i += m2) {
                long w = 1;
                for (int j = 0; j < m; j++) {
                    long t = (w * result[i + j + m]) % MOD;
                    long u = result[i + j];
                    result[i + j] = (u + t) % MOD;
                    result[i + j + m] = (u - t + MOD) % MOD;
                    w = (w * wm) % MOD;
                }
            }
        }

        if (inverse) {
            long nInv = modInv(n);
            for (int i = 0; i < n; i++) {
                result[i] = (result[i] * nInv) % MOD;
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
        }

        int maxSum = n * 9;
        int size = 1;
        int k = 0;
        while (size <= maxSum * 2) {
            size *= 2;
            k++;
        }

        long[] a = new long[size];
        for (int i = 0; i < m; i++) {
            a[nums[i]] = 1;
        }

        long[] transformed = numberTheoreticTransform(a, k, false);
        for (int i = 0; i < size; i++) {
            transformed[i] = modPow(transformed[i], n);
        }
        long[] result = numberTheoreticTransform(transformed, k, true);

        long ans = result[0];
        System.out.println(ans % MOD);
    }
}
